window.AUTH=window.AUTH||{};window.AUTH["96-1671"]={"d":"96-1671","id":"1996/96-1671","n":"Raines v. Byrd","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the appellants","date":"","url":"https://www.justice.gov/osg/media/214816/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/franklin-d-raines-et-al-appellants-v-robert-c-byrd-et-al","n":137},{"k":"reply","label":"Reply brief for the appellants","date":"","url":"https://www.justice.gov/osg/media/215346/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/franklin-d-raines-et-al-appellants-v-robert-c-byrd-et-al-0","n":61}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep521/usrep521811/usrep521811.pdf","tr":false,"items":[{"t":"case","label":"Page Addison v. Holly Hill Fruit Prods., Inc.","cite":"322 U.S. 607","y":1944,"id":"scdb/1943-076","sc":1,"sum":"(1) Judicial construction of \"all\" in the Administrator's definition as meaning \"substantially all\" was not permissible. P. 610. (2) The Administrator's discrimination between canneries having seven or less employees and those having more was unauthorized and invalid. Pp. 611, 618.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"op":3,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"0":"18, 19","1":"4"}},{"t":"case","label":"American Power & Light Co. v. SEC","cite":"329 U.S. 90","y":1946,"id":"scdb/1946-007","sc":1,"op":2,"sum":"that the orders were authorized by § 11 (b) (2) and that the section as so applied is constitutional. Pp. 96, 121.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"117 S. Ct. 1055","y":1997,"id":"1996/95-974","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Bender v. Williamsport Area Sch. Dist.","cite":"475 U.S. 534","y":1986,"id":"1985/84-773","sc":1,"op":4,"sum":"Respondent had no standing to appeal, and therefore the Court of Appeals had no jurisdiction to hear his appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 27, 28","1":"1, 2"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"22, 24, 27, 39","1":"3"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"25,27","1":"20"}},{"t":"case","label":"Cheng Fan Kwok v. INS","cite":"392 U.S. 206","y":1968,"id":"1967/638","sc":1,"sum":"Jurisdietion to review the denial by a district dir(etor of immigration of a stlav of deportation, requested by a Chinese seaian'who had deserted his ship and remained unlawfully in this country, where the pertinent order was not entered in the course of a deportation proceeding conducted under §242 (b) of the Immigration and Nationality Act, is not, under the provisions of § 106 (a), vested exclusively in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Chicago & Grand Trunk Ry. v. Wellman","cite":"143 U.S. 339","y":1892,"id":"scdb/1891-121","sc":1,"op":3,"sum":"The act of the legislature of Michigan of June 28, 1889, (Public Laws of 1889, pp. 282, 283,) fixing the amount per mile to be charged by railways for the transportation of a passenger, violates noprovision in the Constitution of the United States, so far as disclosed by the facts in this case. A legislature has power to fix rates for the transportation of passengers by railways, arid the extent of judicial …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19","1":"4"}},{"t":"case","label":"Cincinnati Soap Co. v. United States","cite":"301 U.S. 308","y":1937,"id":"scdb/1936-117","sc":1,"sum":"Section 602 of the Revenue Act of 1934 imposes a tax of 3 cents per pound upon the first domestic processing of coconut oil, and provides that all such taxes collected with respect to coconut oil wholly of Philippine production, etc., \"shall be held as a separate fund and paid to the Treasury of the Philippine Islands, but if at any time the Philippine Government provides by any law for any subsidy to be paid to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 43","1":"15"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"City of New Haven v. United States","cite":"634 F. Supp. 1449","y":1986,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./634/1449/","by":{"0":"6"}},{"t":"case","label":"Coleman v. Miller","cite":"307 U.S. 433","y":1939,"id":"1900-1940/307us433","sc":1,"op":46,"sum":"The Court held that the Kansas legislators had standing to sue, but found that two of the plaintiffs’ claims raised political questions that could only be resolved by Congress.","sumSrc":"Oyez","by":{"0":"21, 28, 29","1":"8"}},{"t":"case","label":"Diamond v. Charles","cite":"476 U.S. 54","y":1986,"id":"1985/84-1379","sc":1,"op":1,"sum":"Noting that \"a State has standing to defend the constitutionality of its statute\" in federal court.","sumSrc":"opinion","by":{"0":"21"}},{"t":"case","label":"Director, OWCP v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"op":1,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Dugan v. Rank","cite":"372 U.S. 609","y":1963,"id":"1962/31","sc":1,"sum":"Respondents, who are claimants to water rights along the San Joaquin River below the Friant Dan in California, brought suit against the United States, local officials of the United States Bureau of Reclamation, and a number of irrigation and utility districts to enjoin the storing and diversion of water at the dam, which is part of the Central Valley Reclamation Project, authorized by Congress and undertaken by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"FEA v. Algonquin SNG, Inc.","cite":"426 U.S. 548","y":1976,"id":"1975/75-382","sc":1,"sum":"Section 232 (b) authorizes the action taken by the President.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 44"}},{"t":"case","label":"FEC v. NRA Political Victory Fund","cite":"513 U.S. 88","y":1994,"id":"1994/93-1151","sc":1,"sum":"Petitioner Federal Election Commission (FEC) brought this civil action against respondents seeking to enforce a provision of the Federal Election Campaign Act of 1971 (FECA). The District Court ruled against respondents. The Court of Appeals reversed and entered its judgment on October 22, 1993. Without first seeking or obtaining the Solicitor General's authorization, the FEC filed in its own name a petition for a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"FPC v. Hope Natural Gas Co.","cite":"320 U.S. 591","y":1944,"id":"1940-1955/320us591","sc":1,"sum":"1. The validity of an order of the Federal Power Commission fixing rates under the Natural Gas Act is to be determined on judicial review by whether the impact or total effect of the order is just and reasonable rather than by the method of computing the rate base.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42,43"}},{"t":"case","label":"Field v. Clark","cite":"143 U.S. 649","y":1892,"id":"scdb/1891-139","sc":1,"op":1,"sum":"The signing by the Speaker of the House of Representatives and by the President of the Senate, in open session, of an enrolled bill, is an official attestation by the two Houses of such bill as one that has passed Congress; and when the bill thus attested receives the approval of the President, and is deposited in the Department of State according to law, its authentication as a bill that has passed Congress is …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41, 42, 46, 47, 48, 49","1":"17, 19"}},{"t":"case","label":"Gladstone Realtors v. Village of Bellwood","cite":"441 U.S. 91","y":1979,"id":"1978/77-1493","sc":1,"op":1,"sum":"Section 812 of the Fair Housing Act of 1968 (Act) provides that the rights granted by § 804 against racial discrimination in the sales or rental of housing \"may be enforced by civil actions in appropriate United States district courts.\" Respondents (the village of Bellwood, one Negro and four white residents of Bellwood, and one Negro resident of a neighboring municipality) brought separate actions in District Court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Hafer v. Melo","cite":"502 U.S. 21","y":1991,"id":"1991/90-681","sc":1,"sum":"State officers may be held personally liable for damages under § 1983 based upon actions taken in their official capacities.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Heckler v. Chancy","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Henderson v. United States","cite":"116 S. Ct. 1638","y":1996,"id":"1995/95-232","sc":1,"sum":"The Court held that \"[t]he federal rules thus convey a clear message: Complaints are not to be dismissed if served within 120 days, or within such additional time as the court may allow.\".","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Hunt v. Washington State Apple Advertising Comm'n","cite":"432 U.S. 333","y":1977,"id":"1976/76-63","sc":1,"sum":"The Court voted unanimously that the North Carolina regulation was an unconstitutional exercise of the state's power over interstate commerce. Although the regulation was facially neutral, it had a discriminatory impact on the Washington growers while shielding the local growers from the same burden. The regulation removed the competitive advantage gained by the Washington apples from stricter inspection standards.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"passim","1":"12"}},{"t":"case","label":"J.W. Hampton, Jr., & Co. v. United States","cite":"276 U.S. 394","y":1928,"id":"1900-1940/276us394","sc":1,"sum":"The Court held that Congress, within \"defined limits,\" could vest discretion in Executive officers to make public regulations and direct the details of statutory execution. The Court argued that the same principle that allowed Congress to fix rates in interstate commerce also enabled it to remit to a rate-making body under the control of the Executive branch.","sumSrc":"Oyez","by":{"0":"25,42","1":"19"}},{"t":"case","label":"Karcher v. May","cite":"484 U.S. 72","y":1987,"id":"1987/85-1551","sc":1,"sum":"The Court held that once the individuals left their offices, the authority to pursue the lawsuit on behalf of the Legislature passed to their successors. Because Karcher and Orechio’s successors withdrew the appeal, there was no longer an active case or controversy, so the Court had no jurisdiction to hear the case under Article III.","sumSrc":"Oyez","by":{"0":"22,29"}},{"t":"case","label":"Kentucky v. Graham","cite":"473 U.S. 159","y":1985,"id":"1984/84-849","sc":1,"sum":"Section 1988 does not allow attorney's fees to be recovered from a governmental entity when a plaintiff sues governmental employees only in their personal capacities and prevails; accordingly, since this case was necessarily litigated as a personal-capacity and not as an officialcapacity action, it was error to award fees against the Commonwealth.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"La Abra Silver Mining Co. v. United States","cite":"175 U.S. 423","y":1899,"id":"scdb/1899-034","sc":1,"sum":"The Commissioners appointed under the treaty between the United States and Mexico concluded July 4, 1868, and proclaimed February 1, 1869, (15 Stat. 679), having differed in opinion as to the allowance of the claim of the La Abra Silver Mining Company, a New York corporation, against Mexico, the Umpire decided^for that company and allowed its claim, amounting, principal and interest, to the sum of $683,041.32. …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Laird v. Tatum","cite":"408 U.S. 1","y":1972,"id":"1971/71-288","sc":1,"sum":"Respondents' claim that their First Amendment rights are chilled, due to the mere existence of this data-gathering system, does not constitute a justiciable controversy on the basis of the record in this case, disclosing as it does no showing of objective harm or threat of specific future harm. Pp. 3-16. 144 U. S. App. D. C. 72, 444 F. 2d 947, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Lichter v. United States","cite":"334 U.S. 742","y":1948,"id":"scdb/1947-108","sc":1,"sum":"1. The Renegotiation Act is constitutional on its face as authority for the recovery by the United States of \"excessive profits\" (less tax credits) realized by private parties in the circumstances of these cases on subcontracts for war goods in time of war with contractors who were also private parties--even in the absence of contractual provisions for the renegotiation of such profits and even as applied to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42,43"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 38, 43"}},{"t":"case","label":"Loving v. United States","cite":"116 S. Ct. 1737","y":1996,"id":"1995/94-1966","sc":1,"sum":"The Court held that not only does the Constitution require the aggravating factors of the military's death penalty, but that the President's prescription of the challenged aggravating factors did not violate the separation-of-powers principle.","sumSrc":"Oyez","by":{"0":"41, 42","1":"15, 17"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":4,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"19, 23, 30","1":"2"}},{"t":"case","label":"Marsh v. Chambers","cite":"463 U.S. 783","y":1983,"id":"1982/82-23","sc":1,"sum":"As a consequence, the chaplaincy practice had become \"part of the fabric of our society.\" In such circumstances, an invocation for Divine guidance is not an establishment of religion. \"It is,\" wrote Burger, \"simply a tolerable acknowledgment of beliefs widely held among the people of this country.\".","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"McGrain v. Daugherty","cite":"273 U.S. 135","y":1927,"id":"1900-1940/273us135","sc":1,"op":1,"sum":"The Court upheld Daugherty's contempt conviction, establishing a presumption that congressional investigations have a legislative purpose. This presumption was not overcome by showing that the committee also had another purpose, such as exposure of wrongdoing. This presumption would later restrict the Court's hand in clear cases of congressional overreaching while investigating communists after World War II.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Metropolitan Washington Airports Auth. v. Citi- zens for the Abatement of Aircrat Noise, Inc.","cite":"501 U.S. 252","y":1991,"id":"1990/90-906","sc":1,"sum":"An Act of Congress (hereinafter the Transfer Act) authorized the transfer of operating control of Washington National Airport (National) and Dulles International Airport (Dulles) from the federal Department of Transportation to petitioner Metropolitan Washington Airports Authority (MWAA), which was created by a compact between Virginia and the District of Columbia. Both airports are located in the Virginia suburbs …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 32"}},{"t":"case","label":"Miles v. Apez Marine Corp.","cite":"498 U.S. 19","y":1990,"id":"1990/89-1158","sc":1,"sum":"Petitioner Miles, the mother and administratrix of the estate of a seaman killed by a fellow crew member aboard the vessel of respondents (collectively Apex) docked in an American port, sued Apex in District Court, alleging negligence under the Jones Act for failure to prevent the assault, and breach of the warranty of seaworthiness under general maritime law for hiring a crew member unfit to serve. After the court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"38, 41,42,45","1":"14, 15"}},{"t":"case","label":"Moore v. U.S. House of Representatives","cite":"733 F.2d 946","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/733/946/","op":19,"by":{"0":"24, 29","1":"1"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass'n v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Muskrat v. United States","cite":"219 U.S. 346","y":1911,"id":"1900-1940/219us346","sc":1,"op":1,"sum":"The Court ruled that Congress could not create jurisdiction for judicial review of a specific matter by way of legislation.","sumSrc":"Oyez","by":{"0":"33","1":"3"}},{"t":"case","label":"NBC v. United States","cite":"319 U.S. 190","y":1943,"id":"scdb/1942-051","sc":1,"sum":"1. The regulatory powers of the Federal Communications Commission are not limited to the engineering and technical aspects of radio communication.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42,43"}},{"t":"case","label":"National Treasury Employees Union v. United States","cite":"101 F.3d 1423","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/101/1423/","op":1,"by":{"0":"12"}},{"t":"case","label":"New York Central Securities Corp. v. United States","cite":"287 U.S. 12","y":1932,"id":"scdb/1932-039","sc":1,"sum":"(.1) Under subdivision (2) the Commission may authorize a carrier that already controls others by stock ownership, to have control also by lease, for the purpose of securing greater economy and efficiency of operation. The disjunctive phrasing, \"either under a lease or by purchase of stock,\" does not mean that one method must be exclusive of the other. Pp. 22-23. (2) The extent of control allowable by the Commission …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42,43"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"0":"43","1":"10"}},{"t":"case","label":"Ornelas v. United States","cite":"116 S. Ct. 1657","y":1996,"id":"1995/95-5257","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held \"[t]he ultimate questions of reasonable suspicion and probable cause to make a warrantless search should be reviewed de novo.\" The principle details in such a review should be an analysis of events leading up to the search and the objective review of the search.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Powell v. McCormack","cite":"395 U.S. 486","y":1969,"id":"1968/138","sc":1,"op":7,"sum":"After analyzing the Framers' debates on this issue, Chief Justice Warren concluded that since Powell had been lawfully elected by his constituents and since he met the constitutional requirements for membership in the House, that the chamber was powerless to exclude him.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Reno v. Catholic Social Servs., Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"SEC v. United States Realty & Improvement Co.","cite":"310 U.S. 434","y":1940,"id":"scdb/1939-040","sc":1,"sum":"1. A bankruptcy court has jurisdiction to make orders not subject to collateral attack in a proceeding for an \"arrangement\" with unsecured creditors brought by a debtor corporation under Chapter XI of the Chandler Act, although the financial and corporate setup of the debtor are such that adequate protection and relief can not be obtained under the limitations of that chapter but require a reorganization under …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Santobello v. New York","cite":"404 U.S. 257","y":1971,"id":"1971/70-98","sc":1,"sum":"The Court held that a defendant can seek a new trial when a new prosecutor fails to abide by the terms of his predecessor’s plea agreement.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Schlesinger v. Reservists Comm. to Stop the War","cite":"418 U.S. 208","y":1974,"id":"1973/72-1188","sc":1,"op":5,"sum":"Respondents-an association of present and former members of the Armed Forces Reserve opposing United States involvement in Vietnam, and five association members who were United States citizens and taxpayers-brought a class action on behalf, inter alia, of all United States citizens and taxpayers against petitioners, the Secretary of Defense and the three Service Secretaries, challenging the Reserve membership of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"Sibbach v. Wilson & Co.","cite":"312 U.S. 1","y":1941,"id":"scdb/1940-046","sc":1,"sum":"1. Congress has power to regulate the practice and procedure of federal courts, and may exercise it by delegating to the Supreme or other federal courts authority to make rules not inconsistent with the statutes or Constitution of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Sierra Club v. Morton","cite":"405 U.S. 727","y":1972,"id":"1971/70-34","sc":1,"sum":"The Court held that a plaintiff must show that he has suffered a direct injury or will suffer a direct injury as a result of the defendant’s actions in order to have standing to sue under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Simon v. Eastern Kentucky Welfare Rights Org.","cite":"426 U.S. 26","y":1976,"id":"1975/74-1124","sc":1,"op":3,"sum":"The District Court should have granted petitioners' motion to dismiss because respondents failed to establish their standing to bring this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 32","1":"9"}},{"t":"case","label":"Skinner v. Mid-America Pipeline Co.","cite":"490 U.S. 212","y":1989,"id":"1988/87-2098","sc":1,"sum":"Section 7005 of COBRA is not an unconstitutional delegation of the taxing power by Congress to the Executive Branch.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"19"}},{"t":"case","label":"Synar v. United States","cite":"626 F. Supp. 1374","y":1986,"url":"https://www.courtlistener.com/c/F.%20Supp./626/1374/","by":{"0":"42,49"}},{"t":"case","label":"Touby v. United States","cite":"500 U.S. 160","y":1991,"id":"1990/90-6282","sc":1,"sum":"The Court held that the Controlled Substances Act allows the Attorney General to delegate authority to the Drug Enforcement Agency.","sumSrc":"Oyez","by":{"0":"41, 42, 47","1":"18"}},{"t":"case","label":"Train v. City of New York","cite":"420 U.S. 35","y":1975,"id":"1974/73-1377","sc":1,"op":1,"sum":"The 1972 Amendments do not permit the Administrator to allot to the States under § 205 (a) less than the entire amounts authorized to be appropriated by § 207.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 19, 20","1":"5"}},{"t":"case","label":"United States v. Ballin","cite":"144 U.S. 1","y":1892,"id":"scdb/1891-140","sc":1,"op":1,"sum":"The provision in Rule XV of the House of Representatives of the fifty-first Congress, that “on the demand of any member, or at the suggestion of the Speaker, the names of members sufficient to make a quorum in the hall of the house who do not vote shall be noted by the clerk and recorded in the journal, and reported to the Speaker with the names of the members voting, and be counted and,-announced in determining the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"United States v. Lovett","cite":"328 U.S. 303","y":1946,"id":"scdb/1945-030","sc":1,"by":{"0":"26"}},{"t":"case","label":"United States v. Munoz-Flores","cite":"495 U.S. 385","y":1990,"id":"1989/88-1932","sc":1,"op":1,"sum":"After respondent pleaded guilty to two federal misdemeanors, a Federal Magistrate, inter alia, ordered him to pay, as required by 18 U. S. C. § 3013, a monetary \"special assessment\" to the Crime Victims Fund established by the Victims of Crime Act of 1984. He moved to correct his sentence, asserting that the assessments were unconstitutional because Congress had passed §3013 in violation of the Origination Clause, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Richardson","cite":"418 U.S. 166","y":1974,"id":"1973/72-885","sc":1,"op":3,"sum":"The Court held that Richardson did not have standing to sue. Using the two-pronged standing test of Flast v. Cohen (1968), Chief Justice Burger found that there was no \"logical nexus between the status asserted [by Richardson as a taxpayer] and the claim sought to be adjudicated.\" It was clear to Burger that Richardson was not \"a proper and appropriate party to invoke federal judicial power\" on this issue.","sumSrc":"Oyez","by":{"0":"35","1":"4"}},{"t":"case","label":"United States Nat'1 Bank of Oregon v. Independent Ins. Agents of America, Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19"}},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"sum":"Whitmore lacks standing to proceed in this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 18,30"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"42, 43","1":"15"}},{"t":"case","label":"Young v. United States ex rel. Vuitton et Fils S.A.","cite":"481 U.S. 787","y":1987,"id":"1986/85-1329","sc":1,"sum":"The judgment is reversed. 780 F. 2d 179, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25,26"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"const","label":"Article II","by":{"0":"15, 20, 25, 40, 41, 45, 48","1":"17"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"14, 18, 19, 20","1":"1, 2, 3, 9"}},{"t":"law","label":"Pub. L. No. 100-119","url":"https://www.govinfo.gov/link/statute/101/785","by":{"0":"7"}},{"t":"usc","label":"2 U.S.C. § 900","url":"https://www.law.cornell.edu/uscode/text/2/900","subs":["(h)"],"by":{"0":"10, 22, 10"}},{"t":"usc","label":"2 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/2/901","subs":["(a)(l)"],"by":{"0":"10, 10"}},{"t":"usc","label":"2 U.S.C. § 901a","url":"https://www.law.cornell.edu/uscode/text/2/901a","subs":["(a)"],"by":{"0":"10"}},{"t":"usc","label":"2 U.S.C. § 902","url":"https://www.law.cornell.edu/uscode/text/2/902","subs":["(b)"],"by":{"0":"10, 10"}},{"t":"usc","label":"2 U.S.C. § 904","url":"https://www.law.cornell.edu/uscode/text/2/904","subs":["(h)"],"by":{"0":"10"}},{"t":"usc","label":"2 U.S.C. § 906","url":"https://www.law.cornell.edu/uscode/text/2/906","subs":["(1)"],"by":{"0":"10"}},{"t":"usc","label":"2 U.S.C. § 907","url":"https://www.law.cornell.edu/uscode/text/2/907","by":{"0":"9"}},{"t":"law","label":"Pub. L. No. 101-508","url":"https://www.govinfo.gov/link/statute/104/1388","by":{"0":"10"}},{"t":"usc","label":"21 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/21/801","by":{"0":"48"}},{"t":"usc","label":"2 U.S.C. § 6085","url":"https://www.law.cornell.edu/uscode/text/2/6085","subs":["(c)"],"by":{"0":"47"}},{"t":"usc","label":"33 U.S.C. § 1281","url":"https://www.law.cornell.edu/uscode/text/33/1281","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 92-500","url":"https://www.govinfo.gov/link/statute/86/833","by":{"0":"7"}},{"t":"usc","label":"2 U.S.C. § 681","url":"https://www.law.cornell.edu/uscode/text/2/681","stext":{"head":"§681. Disclaimer","paras":[[0,"Nothing contained in this Act, or in any amendments made by this Act, shall be construed as—"],[1,"(1) asserting or conceding the constitutional powers or limitations of either the Congress or the President;"],[1,"(2) ratifying or approving any impoundment heretofore or hereafter executed or approved by the President or any other Federal officer or employee, except insofar as pursuant to statutory authorization then in effect;"],[1,"(3) affecting in any way the claims or defenses of any party to litigation concerning any impoundment; or"],[1,"(4) superseding any provision of law which requires the obligation of budget authority or the making of outlays thereunder."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/2/681?type=usc&year=mostrecent&link-type=html"},"head":"§681. Disclaimer","tname":"The Congress","by":{"0":"7","1":"11"}},{"t":"usc","label":"31 U.S.C. § 665","url":"https://www.law.cornell.edu/uscode/text/31/665","subs":["(1976)"],"by":{"0":"8"}},{"t":"usc","label":"2 U.S.C. § 682","url":"https://www.law.cornell.edu/uscode/text/2/682","subs":["(1)","(3)"],"by":{"0":"7, 7"}},{"t":"usc","label":"2 U.S.C. § 683","url":"https://www.law.cornell.edu/uscode/text/2/683","subs":["(1982)"],"by":{"0":"7"}},{"t":"usc","label":"2 U.S.C. § 684","url":"https://www.law.cornell.edu/uscode/text/2/684","subs":["(1982)"],"by":{"0":"7"}},{"t":"usc","label":"2 U.S.C. § 691","url":"https://www.law.cornell.edu/uscode/text/2/691","subs":["(a)","(a)(A)","(a)(B)","(b)","(a)(A)(i)","(a)(3)"],"op":3,"tname":"The Congress","by":{"0":"8, 35, 44, 11, 44, 10, 45, 2, 8, 8, 36","1":"11, 11, 11, 19, 11, 3"}},{"t":"usc","label":"2 U.S.C. § 691a","url":"https://www.law.cornell.edu/uscode/text/2/691a","subs":["(b)","(c)(1)"],"stext":{"head":"§691a. Special messages","paras":[[0,"(a) In general"],[0,"For each law from which a cancellation has been made under this subchapter, the President shall transmit a single special message to the Congress."],[0,"(b) Contents"],[0,"(1) The special message shall specify—"],[1,"(A) the dollar amount of discretionary budget authority, item of new direct spending, or limited tax benefit which has been canceled, and provide a corresponding reference number for each cancellation;"],[1,"(B) the determinations required under section 691(a) of this title, together with any supporting material;"],[1,"(C) the reasons for the cancellation;"],[1,"(D) to the maximum extent practicable, the estimated fiscal, economic, and budgetary effect of the cancellation;"],[1,"(E) all facts, circumstances and considerations relating to or bearing upon the cancellation, and to the maximum extent practicable, the estimated effect of the cancellation upon the objects, purposes and programs for which the canceled authority was provided; and"],[1,"(F) include the adjustments that will be made pursuant to section 691c of this title to the discretionary spending limits under section 901(c) of this title and an evaluation of the effects of those adjustments upon the sequestration procedures of section 901 of this title."],[0,"(2) In the case of a cancellation of any dollar amount of discretionary budget authority or item of new direct spending, the special message shall also include, if applicable—"],[1,"(A) any account, department, or establishment of the Government for which such budget authority was to have been available for obligation and the specific project or governmental functions involved;"],[1,"(B) the specific States and congressional districts, if any, affected by the cancellation; and"],[1,"(C) the total number of cancellations imposed during the current session of Congress on States and congressional districts identified in subparagraph (B)."],[0,"(c) Transmission of special messages to House and Senate"],[0,"(1) The President shall transmit to the Congress each special message under this subchapter within five calendar days (excluding Sundays) after enactment of the law to which the cancellation applies. Each special message shall be transmitted to the House of Representatives and the Senate on the same calendar day. Such special message shall be delivered to the Clerk of the House of Representatives if the House is not in session, and to the Secretary of the Senate if the Senate is not in session."],[0,"(2) Any special message transmitted under this subchapter shall be printed in the first issue of the Federal Register published after such transmittal."]],"more":false,"ed":"2003","src":"https://www.govinfo.gov/link/uscode/2/691a?type=usc&year=mostrecent&link-type=html"},"head":"§691a. Special messages","tname":"The Congress","by":{"0":"11, 45, 10","1":"11"}},{"t":"usc","label":"2 U.S.C. § 691b","url":"https://www.law.cornell.edu/uscode/text/2/691b","subs":["(a)","(b)"],"stext":{"head":"§691b. Cancellation effective unless disapproved","paras":[[0,"(a) In general"],[0,"The cancellation of any dollar amount of discretionary budget authority, item of new direct spending, or limited tax benefit shall take effect upon receipt in the House of Representatives and the Senate of the special message notifying the Congress of the cancellation. If a disapproval bill for such special message is enacted into law, then all cancellations disapproved in that law shall be null and void and any such dollar amount of discretionary budget authority, item of new direct spending, or limited tax benefit shall be effective as of the original date provided in the law to which the cancellation applied."],[0,"(b) Commensurate reductions in discretionary budget authority"],[0,"Upon the cancellation of a dollar amount of discretionary budget authority under subsection (a) of this section, the total appropriation for each relevant account of which that dollar amount is a part shall be simultaneously reduced by the dollar amount of that cancellation."]],"more":false,"ed":"2003","src":"https://www.govinfo.gov/link/uscode/2/691b?type=usc&year=mostrecent&link-type=html"},"head":"§691b. Cancellation effective unless disapproved","tname":"The Congress","by":{"0":"11, 10","1":"10"}},{"t":"usc","label":"2 U.S.C. § 691c","url":"https://www.law.cornell.edu/uscode/text/2/691c","subs":["(a)","(a)(1)(B)","(a)(2)(B)","(b)"],"stext":{"head":"§691c. Deficit reduction","paras":[[0,"(a) In general"],[0,"(1) Discretionary budget authority"],[1,"OMB shall, for each dollar amount of discretionary budget authority and for each item of new direct spending canceled from an appropriation law under section 691(a) of this title—"],[2,"(A) reflect the reduction that results from such cancellation in the estimates required by section 251(a)(7) of the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 901(a)(7)] in accordance with that Act [2 U.S.C. 900 et seq.], including an estimate of the reduction of the budget authority and the reduction in outlays flowing from such reduction of budget authority for each outyear; and"],[2,"(B) include a reduction to the discretionary spending limits for budget authority and outlays in accordance with the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 900 et seq.] for each applicable fiscal year set forth in section 251(c) of the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 901(c)] by amounts equal to the amounts for each fiscal year estimated pursuant to subparagraph (A)."],[0,"(2) Direct spending and limited tax benefits"],[1,"(A) OMB shall, for each item of new direct spending or limited tax benefit canceled from a law under section 691(a) of this title, estimate the deficit decrease caused by the cancellation of such item or benefit in that law and include such estimate as a separate entry in the report prepared pursuant to section 252(d) of the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 902(d)]."],[1,"(B) OMB shall not include any change in the deficit resulting from a cancellation of any item of new direct spending or limited tax benefit, or the enactment of a disapproval bill for any such cancellation, under this subchapter in the estimates and reports required by sections 252(b) and 254 of the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 902(b), 904]."],[0,"(b) Adjustments to spending limits"],[0,"After ten calendar days (excluding Sundays) after the expiration of the time period in section 691d(b)(1) of this title for expedited congressional consideration of a disapproval bill for a special message containing a cancellation of discretionary budget authority, OMB shall make the reduction included in subsection (a)(1)(B) of this section as part of the next sequester report required by section 254 of the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 904]."],[0,"(c) Exception"],[0,"Subsection (b) of this section shall not apply to a cancellation if a disapproval bill or other law that disapproves that cancellation is enacted into law prior to 10 calendar days (excluding Sundays) after the expiration of the time period set forth in section 691d(b)(1) of this title."],[0,"(d) Congressional Budget Office estimates"],[0,"As soon as practicable after the President makes a cancellation from a law under section 691(a) of this title, the Director of the Congressional Budget Office shall provide the Committees on the Budget of the House of Representatives and the Senate with an estimate of the reduction of the budget authority and the reduction in outlays flowing from such reduction of budget authority for each outyear."]],"more":false,"ed":"2003","src":"https://www.govinfo.gov/link/uscode/2/691c?type=usc&year=mostrecent&link-type=html"},"head":"§691c. Deficit reduction","tname":"The Congress","by":{"0":"10, 10, 10, 10, 10","1":"10"}},{"t":"usc","label":"2 U.S.C. § 691d","url":"https://www.law.cornell.edu/uscode/text/2/691d","stext":{"head":"§691d. Expedited congressional consideration of disapproval bills","paras":[[0,"(a) Receipt and referral of special message"],[0,"Each special message transmitted under this subchapter shall be referred to the Committee on the Budget and the appropriate committee or committees of the Senate and the Committee on the Budget and the appropriate committee or committees of the House of Representatives. Each such message shall be printed as a document of the House of Representatives."],[0,"(b) Time period for expedited procedures"],[0,"(1) There shall be a congressional review period of 30 calendar days of session, beginning on the first calendar day of session after the date on which the special message is received in the House of Representatives and the Senate, during which the procedures contained in this section shall apply to both Houses of Congress."],[0,"(2) In the House of Representatives the procedures set forth in this section shall not apply after the end of the period described in paragraph (1)."],[0,"(3) If Congress adjourns at the end of a Congress prior to the expiration of the period described in paragraph (1) and a disapproval bill was then pending in either House of Congress or a committee thereof (including a conference committee of the two Houses of Congress), or was pending before the President, a disapproval bill for the same special message may be introduced within the first five calendar days of session of the next Congress and shall be treated as a disapproval bill under this subchapter, and the time period described in paragraph (1) shall commence on the day of introduction of that disapproval bill."],[0,"(c) Introduction of disapproval bills"],[0,"(1) In order for a disapproval bill to be considered under the procedures set forth in this section, the bill must meet the definition of a disapproval bill and must be introduced no later than the fifth calendar day of session following the beginning of the period described in subsection (b)(1) of this section."],[0,"(2) In the case of a disapproval bill introduced in the House of Representatives, such bill shall include in the first blank space referred to in section 691e(6)(C) of this title a list of the reference numbers for all cancellations made by the President in the special message to which such disapproval bill relates."],[0,"(d) Consideration in House of Representatives"],[0,"(1) Any committee of the House of Representatives to which a disapproval bill is referred shall report it without amendment, and with or without recommendation, not later than the seventh calendar day of session after the date of its introduction. If any committee fails to report the bill within that period, it is in order to move that the House discharge the committee from further consideration of the bill, except that such a motion may not be made after the committee has reported a disapproval bill with respect to the same special message. A motion to discharge may be made only by a Member favoring the bill (but only at a time or place designated by the Speaker in the legislative schedule of the day after the calendar day on which the Member offering the motion announces to the House his intention to do so and the form of the motion). The motion is highly privileged. Debate thereon shall be limited to not more than one hour, the time to be divided in the House equally between a proponent and an opponent. The previous question shall be considered as ordered on the motion to its adoption without intervening motion. A motion to reconsider the vote by which the motion is agreed to or disagreed to shall not be in order."],[0,"(2) After a disapproval bill is reported or a committee has been discharged from further consideration, it is in order to move that the House resolve into the Committee of the Whole House on the State of the Union for consideration of the bill. If reported and the report has been available for at least one calendar day, all points of order against the bill and against consideration of the bill are waived. If discharged, all points of order against the bill and against consideration of the bill are waived. The motion is highly privileged. A motion to reconsider the vote by which the motion is agreed to or disagreed to shall not be in order. During consideration of the bill in the Committee of the Whole, the first reading of the bill shall be dispensed with. General debate shall proceed, shall be confined to the bill, and shall not exceed one hour equally divided and controlled by a proponent and an opponent of the bill. The bill shall be considered as read for amendment under the five-minute rule. Only one motion to rise shall be in order, except if offered by the manager. No amendment to the bill is in order, except any Member if supported by 49 other Members (a quorum being present) may offer an amendment striking the reference number or numbers of a cancellation or cancellations from the bill. Consideration of the bill for amendment shall not exceed one hour excluding time for recorded votes and quorum calls. No amendment shall be subject to further amendment, except pro forma amendments for the purposes of debate only. At the conclusion of the consideration of the bill for amendment, the Committee shall rise and report the bill to the House with such amendments as may have been adopted. The previous question shall be considered as ordered on the bill and amendments thereto to final passage without intervening motion. A motion to reconsider the vote on passage of the bill shall not be in order."],[0,"(3) Appeals from decisions of the Chair regarding application of the rules of the House of Representatives to the procedure relating to a disapproval bill shall be decided without debate."],[0,"(4) It shall not be in order to consider under this subsection more than one disapproval bill for the same special message except for consideration of a similar Senate bill (unless the House has already rejected a disapproval bill for the same special message) or more than one motion to discharge described in paragraph (1) with respect to a disapproval bill for that special message."],[0,"(e) Consideration in Senate"],[0,"(1) Referral and reporting"],[1,"Any disapproval bill introduced in the Senate shall be referred to the appropriate committee or committees. A committee to which a disapproval bill has been referred shall report the bill not later than the seventh day of session following the date of introduction of that bill. If any committee fails to report the bill within that period, that committee shall be automatically discharged from further consideration of the bill and the bill shall be placed on the Calendar."],[0,"(2) Disapproval bill from House"],[1,"When the Senate receives from the House of Representatives a disapproval bill, such bill shall not be referred to committee and shall be placed on the Calendar."],[0,"(3) Consideration of single disapproval bill"],[1,"After the Senate has proceeded to the consideration of a disapproval bill for a special message, then no other disapproval bill originating in that same House relating to that same message shall be subject to the procedures set forth in this subsection."],[0,"(4) Amendments"],[0,"(A) Amendments in order"],[2,"The only amendments in order to a disapproval bill are—"],[3,"(i) an amendment that strikes the reference number of a cancellation from the disapproval bill; and"],[3,"(ii) an amendment that only inserts the reference number of a cancellation included in the special message to which the disapproval bill relates that is not already contained in such bill."],[0,"(B) Waiver or appeal"],[2,"An affirmative vote of three-fifths of the Senators, duly chosen and sworn, shall be required in the Senate—"],[3,"(i) to waive or suspend this paragraph; or"],[3,"(ii) to sustain an appeal of the ruling of the Chair on a point of order raised under this paragraph."],[0,"(5) Motion nondebatable"],[1,"A motion to proceed to consideration of a disapproval bill under this subsection shall not be debatable. It shall not be in order to move to reconsider the vote by which the motion to proceed was adopted or rejected, although subsequent motions to proceed may be made under this paragraph."],[0,"(6) Limit on consideration"],[1,"(A) After no more than 10 hours of consideration of a disapproval bill, the Senate shall proceed, without intervening action or debate (except as permitted under paragraph (9)), to vote on the final disposition thereof to the exclusion of all amendments not then pending and to the exclusion of all motions, except a motion to reconsider or to table."],[1,"(B) A single motion to extend the time for consideration under subparagraph (A) for no more than an additional five hours is in order prior to the expiration of such time and shall be decided without debate."],[1,"(C) The time for debate on the disapproval bill shall be equally divided between the Majority Leader and the Minority Leader or their designees."],[0,"(7) Debate on amendments"],[1,"Debate on any amendment to a disapproval bill shall be limited to one hour, equally divided and controlled by the Senator proposing the amendment and the majority manager, unless the majority manager is in favor of the amendment, in which case the minority manager shall be in control of the time in opposition."]],"more":true,"ed":"2003","src":"https://www.govinfo.gov/link/uscode/2/691d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§691d. Expedited congressional consideration of disapproval bills","tname":"The Congress","by":{"0":"11"}},{"t":"usc","label":"2 U.S.C. § 691e","url":"https://www.law.cornell.edu/uscode/text/2/691e","subs":["(4)(A)","(4)(C)","(5)","(6)","(7)(A)","(7)(A)(ii)","(8)","(9)(A)"],"stext":{"head":"§691e. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Appropriation law"],[1,"The term “appropriation law” means an Act referred to in section 105 of title 1, including any general or special appropriation Act, or any Act making supplemental, deficiency, or continuing appropriations, that has been signed into law pursuant to Article I, section 7, of the Constitution of the United States."],[0,"(2) Calendar day"],[1,"The term “calendar day” means a standard 24-hour period beginning at midnight."],[0,"(3) Calendar days of session"],[1,"The term “calendar days of session” shall mean only those days on which both Houses of Congress are in session."],[0,"(4) Cancel"],[1,"The term “cancel” or “cancellation” means—"],[2,"(A) with respect to any dollar amount of discretionary budget authority, to rescind;"],[2,"(B) with respect to any item of new direct spending—"],[3,"(i) that is budget authority provided by law (other than an appropriation law), to prevent such budget authority from having legal force or effect;"],[3,"(ii) that is entitlement authority, to prevent the specific legal obligation of the United States from having legal force or effect; or"],[3,"(iii) through the food stamp program, to prevent the specific provision of law that results in an increase in budget authority or outlays for that program from having legal force or effect; and"],[2,"(C) with respect to a limited tax benefit, to prevent the specific provision of law that provides such benefit from having legal force or effect."],[0,"(5) Direct spending"],[1,"The term “direct spending” means—"],[2,"(A) budget authority provided by law (other than an appropriation law);"],[2,"(B) entitlement authority; and"],[2,"(C) the food stamp program."],[0,"(6) Disapproval bill"],[1,"The term “disapproval bill” means a bill or joint resolution which only disapproves one or more cancellations of dollar amounts of discretionary budget authority, items of new direct spending, or limited tax benefits in a special message transmitted by the President under this subchapter and—"],[2,"(A) the title of which is as follows: “A bill disapproving the cancellations transmitted by the President on ____________”, the blank space being filled in with the date of transmission of the relevant special message and the public law number to which the message relates;"],[2,"(B) which does not have a preamble; and"],[2,"(C) which provides only the following after the enacting clause: “That Congress disapproves of cancellations ________”, the blank space being filled in with a list by reference number of one or more cancellations contained in the President's special message, “as transmitted by the President in a special message on ________”, the blank space being filled in with the appropriate date, “regarding ________.”, the blank space being filled in with the public law number to which the special message relates."],[0,"(7) Dollar amount of discretionary budget authority"],[1,"(A) Except as provided in subparagraph (B), the term “dollar amount of discretionary budget authority” means the entire dollar amount of budget authority—"],[2,"(i) specified in an appropriation law, or the entire dollar amount of budget authority required to be allocated by a specific proviso in an appropriation law for which a specific dollar figure was not included;"],[2,"(ii) represented separately in any table, chart, or explanatory text included in the statement of managers or the governing committee report accompanying such law;"],[2,"(iii) required to be allocated for a specific program, project, or activity in a law (other than an appropriation law) that mandates the expenditure of budget authority from accounts, programs, projects, or activities for which budget authority is provided in an appropriation law;"],[2,"(iv) represented by the product of the estimated procurement cost and the total quantity of items specified in an appropriation law or included in the statement of managers or the governing committee report accompanying such law; or"],[2,"(v) represented by the product of the estimated procurement cost and the total quantity of items required to be provided in a law (other than an appropriation law) that mandates the expenditure of budget authority from accounts, programs, projects, or activities for which budget authority is provided in an appropriation law."],[1,"(B) The term “dollar amount of discretionary budget authority” does not include—"],[2,"(i) direct spending;"],[2,"(ii) budget authority in an appropriation law which funds direct spending provided for in other law;"],[2,"(iii) any existing budget authority rescinded or canceled in an appropriation law; or"],[2,"(iv) any restriction, condition, or limitation in an appropriation law or the accompanying statement of managers or committee reports on the expenditure of budget authority for an account, program, project, or activity, or on activities involving such expenditure."],[0,"(8) Item of new direct spending"],[1,"The term “item of new direct spending” means any specific provision of law that is estimated to result in an increase in budget authority or outlays for direct spending relative to the most recent levels calculated pursuant to section 907 of this title."],[0,"(9) Limited tax benefit"],[1,"(A) The term “limited tax benefit” means—"],[2,"(i) any revenue-losing provision which provides a Federal tax deduction, credit, exclusion, or preference to 100 or fewer beneficiaries under title 26 in any fiscal year for which the provision is in effect; and"],[2,"(ii) any Federal tax provision which provides temporary or permanent transitional relief for 10 or fewer beneficiaries in any fiscal year from a change to title 26."],[1,"(B) A provision shall not be treated as described in subparagraph (A)(i) if the effect of that provision is that—"],[2,"(i) all persons in the same industry or engaged in the same type of activity receive the same treatment;"],[2,"(ii) all persons owning the same type of property, or issuing the same type of investment, receive the same treatment; or"],[2,"(iii) any difference in the treatment of persons is based solely on—"],[3,"(I) in the case of businesses and associations, the size or form of the business or association involved;"],[3,"(II) in the case of individuals, general demographic conditions, such as income, marital status, number of dependents, or tax return filing status;"],[3,"(III) the amount involved; or"],[3,"(IV) a generally-available election under title 26."],[1,"(C) A provision shall not be treated as described in subparagraph (A)(ii) if—"],[2,"(i) it provides for the retention of prior law with respect to all binding contracts or other legally enforceable obligations in existence on a date contemporaneous with congressional action specifying such date; or"],[2,"(ii) it is a technical correction to previously enacted legislation that is estimated to have no revenue effect."],[1,"(D) For purposes of subparagraph (A)—"],[2,"(i) all businesses and associations which are related within the meaning of sections 707(b) and 1563(a) of title 26 shall be treated as a single beneficiary;"],[2,"(ii) all qualified plans of an employer shall be treated as a single beneficiary;"],[2,"(iii) all holders of the same bond issue shall be treated as a single beneficiary; and"],[2,"(iv) if a corporation, partnership, association, trust or estate is the beneficiary of a provision, the shareholders of the corporation, the partners of the partnership, the members of the association, or the beneficiaries of the trust or estate shall not also be treated as beneficiaries of such provision."],[1,"(E) For purposes of this paragraph, the term “revenue-losing provision” means any provision which results in a reduction in Federal tax revenues for any one of the two following periods—"],[2,"(i) the first fiscal year for which the provision is effective; or"],[2,"(ii) the period of the 5 fiscal years beginning with the first fiscal year for which the provision is effective."],[1,"(F) The terms used in this paragraph shall have the same meaning as those terms have generally in title 26, unless otherwise expressly provided."],[0,"(10) OMB"],[1,"The term “OMB” means the Director of the Office of Management and Budget."]],"more":false,"ed":"2003","src":"https://www.govinfo.gov/link/uscode/2/691e?type=usc&year=mostrecent&link-type=html"},"head":"§691e. Definitions","tname":"The Congress","by":{"0":"9, 48, 9, 9, 11, 35, 8, 8, 9, 45, 9","1":"10, 10"}},{"t":"usc","label":"2 U.S.C. § 691f","url":"https://www.law.cornell.edu/uscode/text/2/691f","subs":["(a)","(b)","(c)"],"by":{"0":"9, 9, 9"}},{"t":"usc","label":"2 U.S.C. § 691-691f","url":"https://www.law.cornell.edu/uscode/text/2/691-691f","by":{"0":"8"}},{"t":"usc","label":"2 U.S.C. § 692","url":"https://www.law.cornell.edu/uscode/text/2/692","subs":["(a)(1)","(b)","(c)","(a)(l)"],"stext":{"head":"§692. Judicial review","paras":[[0,"(a) Expedited review"],[0,"(1) Any Member of Congress or any individual adversely affected by part C of title X of the Congressional Budget and Impoundment Control Act of 1974 [2 U.S.C. 691 et seq.] may bring an action, in the United States District Court for the District of Columbia, for declaratory judgment and injunctive relief on the ground that any provision of this part violates the Constitution."],[0,"(2) A copy of any complaint in an action brought under paragraph (1) shall be promptly delivered to the Secretary of the Senate and the Clerk of the House of Representatives, and each House of Congress shall have the right to intervene in such action."],[0,"(3) Nothing in this section or in any other law shall infringe upon the right of the House of Representatives to intervene in an action brought under paragraph (1) without the necessity of adopting a resolution to authorize such intervention."],[0,"(b) Appeal to Supreme Court"],[0,"Notwithstanding any other provision of law, any order of the United States District Court for the District of Columbia which is issued pursuant to an action brought under paragraph (1) of subsection (a) of this section shall be reviewable by appeal directly to the Supreme Court of the United States. Any such appeal shall be taken by a notice of appeal filed within 10 calendar days after such order is entered; and the jurisdictional statement shall be filed within 30 calendar days after such order is entered. No stay of an order issued pursuant to an action brought under paragraph (1) of subsection (a) of this section shall be issued by a single Justice of the Supreme Court."],[0,"(c) Expedited consideration"],[0,"It shall be the duty of the District Court for the District of Columbia and the Supreme Court of the United States to advance on the docket and to expedite to the greatest possible extent the disposition of any matter brought under subsection (a) of this section."]],"more":false,"ed":"2003","src":"https://www.govinfo.gov/link/uscode/2/692?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§692. Judicial review","tname":"The Congress","by":{"0":"13, 14, 1, 14","1":"3"}},{"t":"law","label":"Pub. L. No. 90-364","url":"https://www.govinfo.gov/link/statute/82/251","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 91-47","url":"https://www.govinfo.gov/link/statute/83/82","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 91-305","url":"https://www.govinfo.gov/link/statute/84/376","by":{"0":"6"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(h)"],"by":{"0":"47"}},{"t":"usc","label":"2 U.S.C. § 288b","url":"https://www.law.cornell.edu/uscode/text/2/288b","subs":["(b)"],"by":{"0":"27"}},{"t":"usc","label":"5 U.S.C. § 5303","url":"https://www.law.cornell.edu/uscode/text/5/5303","subs":["(b)(1)"],"by":{"0":"47"}},{"t":"usc","label":"5 U.S.C. § 5304a","url":"https://www.law.cornell.edu/uscode/text/5/5304a","subs":["(a)"],"by":{"0":"47"}},{"t":"usc","label":"10 U.S.C. § 7309","url":"https://www.law.cornell.edu/uscode/text/10/7309","subs":["(b)"],"by":{"0":"47"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(b)"],"by":{"0":"49"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","subs":["(b)(2)"],"by":{"0":"48"}},{"t":"case","label":"Alaska Airlines, Inc. v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Bengzon v. Secretary of Justice","cite":"299 U.S. 410","y":1937,"id":"scdb/1936-135","sc":1,"sum":"1. An appropriation bill is one the primary and specific aim of which is to make appropriations of money from the public treasury.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Bennett v. Spear","cite":"117 S. Ct. 1154","y":1997,"id":"1996/95-813","sc":1,"op":2,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Bowles v. Willingham","cite":"321 U.S. 503","y":1944,"id":"scdb/1943-042","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942 and § 24 (1) of the Judicial Code, and in view of § 204 (d) of the Act, a federal district court in a suit by the Administrator has authority to enjoin a proceeding in a state court to restrain issuance by the Administrator of rent orders; and § 265 of the Judicial Code, forbidding federal courts to enjoin proceedings in state courts, is inapplicable.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Flast v. Cohen","cite":"392 U.S. 83","y":1968,"id":"1967/416","sc":1,"op":1,"sum":"The Court held that Flast had met both parts of the test.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Goldwater v. Carter","cite":"444 U.S. 996","y":1979,"id":"1979/79-856","sc":1,"sum":"Without oral argument, the divided justices found that the case was not justiciable. Rehnquist led a group of four others who believed that the issue involved a political question, namely, how the President and Congress would conduct the nation's foreign affairs. Justice Powell did not find the case ripe for judicial review.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Reeside v. Walker","cite":"52 U.S. 271","y":1851,"url":"https://supreme.justia.com/cases/federal/us/52/271/","sc":1,"by":{"1":"10"}},{"t":"case","label":"Skaggs v. Carle","cite":"110 F.3d 831","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/110/831/","op":1,"by":{"1":"7"}},{"t":"case","label":"United States v. Will","cite":"449 U.S. 200","y":1980,"id":"1980/79-983","sc":1,"op":1,"sum":"In two of the years in question, Congress effectively revoked automatic pay increases after the statutes guaranteeing those increases had already taken effect. This amounted to a reduction in salaries for judges and violated the Compensation Clause.","sumSrc":"Oyez","by":{"1":"1"}},{"t":"case","label":"Valley Forge Christian College v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"op":8,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"1":"3-4"}},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","by":{"1":"10"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"7"}},{"t":"usc","label":"7 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/7/601","by":{"1":"18"}},{"t":"usc","label":"7 U.S.C. § 613","url":"https://www.law.cornell.edu/uscode/text/7/613","by":{"1":"18"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"1":"7"}},{"t":"usc","label":"1 U.S.C. § 108","url":"https://www.law.cornell.edu/uscode/text/1/108","by":{"1":"7"}},{"t":"usc","label":"1 U.S.C. § 109","url":"https://www.law.cornell.edu/uscode/text/1/109","by":{"1":"7"}},{"t":"usc","label":"5 U.S.C. § 302","url":"https://www.law.cornell.edu/uscode/text/5/302","subs":["(b)"],"by":{"1":"7"}},{"t":"usc","label":"21 U.S.C. § 811","url":"https://www.law.cornell.edu/uscode/text/21/811","subs":["(a)(l)"],"by":{"1":"18"}},{"t":"usc","label":"21 U.S.C. § 812","url":"https://www.law.cornell.edu/uscode/text/21/812","by":{"1":"18"}},{"t":"usc","label":"22 U.S.C. § 1965","url":"https://www.law.cornell.edu/uscode/text/22/1965","by":{"1":"18"}},{"t":"usc","label":"31 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/31/1301","subs":["(C)","(d)"],"by":{"1":"7, 7"}}]};